  function statusMessage(o){
    const items=o.items||[],released=items.filter(x=>Number(x.released_quantity||0)>0),pending=items.filter(x=>remaining(x)>0),partialReleased=released.length>0;
    const headline={pendente:'PEDIDO RECEBIDO — AGUARDANDO SEPARAÇÃO',separado:'PEDIDO SEPARADO E PRONTO PARA RETIRADA',parcial:'LIBERAÇÃO PARCIAL REALIZADA',liberado:'PEDIDO TOTALMENTE LIBERADO',cancelado:partialReleased?'SALDO RESTANTE DO PEDIDO CANCELADO':'PEDIDO CANCELADO'}[o.status]||statusLabel(o.status);
    const lines=['*VALE DA SERRA LATICÍNIOS*',`*ATUALIZAÇÃO DO PEDIDO #${String(o.id).slice(0,8).toUpperCase()}*`,'',`Olá, ${o.producer_name}.`,`*Status: ${headline}*`,'', '*Produtos do pedido:*',...items.map(x=>`• ${x.product_name}: ${num(x.quantity)} ${x.unit||'un'}`)];
    if(released.length)lines.push('','*Já liberado:*',...released.map(x=>`• ${x.product_name}: ${num(x.released_quantity||0)} ${x.unit||'un'}`));
    if(pending.length&&o.status!=='cancelado')lines.push('','*Ainda reservado:*',...pending.map(x=>`• ${x.product_name}: ${num(remaining(x))} ${x.unit||'un'}`));
    lines.push('',`Forma de pagamento: ${payLabel(o.payment_method)}`,`Valor total do pedido: ${money(o.total)}`);
    if(o.observation)lines.push(`Observação: ${o.observation}`);
    lines.push('','Vale da Serra — valorizando o produtor rural.');return lines.join('\n');
  }
