  function unitSummary(products,key){
    const groups={};for(const p of products){const value=Number(p[key]??0);if(value<=1e-9)continue;const unit=String(p.unit||'un').toLocaleLowerCase('pt-BR');groups[unit]=(groups[unit]||0)+value}
    const parts=Object.entries(groups).map(([u,v])=>`${num(v)} ${u}${u==='saco'&&Math.abs(v-1)>1e-9?'s':''}`);return parts.join(' • ')||'0';
  }
  function weightEquivalent(products,key){return products.reduce((s,p)=>{const q=Number(p[key]??0),u=String(p.unit||'').toLowerCase();if(u==='kg')return s+q;const w=Number(p.package_weight_kg||0);return s+(w>0?q*w:0)},0)}
