    estoqueCarregar=async function(){
      try{const [p,m,o]=await Promise.all([api('/api/inventory/products?ts='+Date.now()),api('/api/inventory/movements?ts='+Date.now()),api('/api/inventory/orders?status=ativos&ts='+Date.now())]);EST.produtos=p.products||[];EST.movimentos=m.movements||[];S.products=EST.produtos;S.activeOrders=o.orders||[];const sel=$('#estMovProd');if(sel)sel.innerHTML='<option value="">Selecione o produto</option>'+EST.produtos.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if(typeof estoqueProdutorOptions==='function')estoqueProdutorOptions();renderDesktopInventory();if(typeof estoqueRenderMovimentos==='function')estoqueRenderMovimentos();galAtualizarVenda();updatePendingBadge()}catch(e){const out=$('#estMsg');if(out)out.textContent='❌ '+e.message}
    };
