    galAtualizarVenda=function(){const p=EST.produtos.find(x=>String(x.id)===String($('#estMovProd')?.value)),q=Number($('#estMovQtd')?.value||0),price=Number(p?.unit_price||0),available=Number(p?.available??p?.balance??0);if($('#estMovValor'))$('#estMovValor').value=price;if($('#galVendaUn'))$('#galVendaUn').value=p?.unit||'-';if($('#galPrecoTxt'))$('#galPrecoTxt').textContent=money(price)+(p?' / '+p.unit:'');if($('#galSaldoTxt'))$('#galSaldoTxt').textContent=p?num(available)+' '+p.unit:'0';if($('#galTotal'))$('#galTotal').textContent=money(q*price)};
