  async function updatePendingBadge(){try{const j=await api('/api/inventory/orders?status=ativos&ts='+Date.now()),orders=j.orders||[];S.activeOrders=orders;const count=$('#v133PendingCount');if(count)count.textContent=orders.length;renderDesktopInventory();return orders}catch(_){return[]}}
  async function refreshAll(){try{await updateDebts()}catch(_){}try{if(typeof estoqueCarregar==='function'&&document.getElementById('estoque'))await estoqueCarregar();else if(window.GalpaoMobile?.reload)await window.GalpaoMobile.reload()}catch(_){}await updatePendingBadge()}

  async function updateDebts(){const j=await api('/api/state?ts='+Date.now()),list=Array.isArray(j.data?.debitos)?j.data.debitos:null;if(list){try{if(typeof debitos!=='undefined')debitos=list}catch(_){}localStorage.setItem('vds_debitos_v1',JSON.stringify(list));try{if(typeof renderDebitos==='function')renderDebitos()}catch(_){}try{if(typeof window.v132MobileReloadState==='function')await window.v132MobileReloadState()}catch(_){}}return j.data}
  window.v133AtualizarDebitosServidor=updateDebts;window.v132AtualizarDebitosServidor=updateDebts;
  function debtSource(d){const o=String(d.origem||'').toLowerCase(),id=String(d.id||''),desc=String(d.descricao||'');if(o==='galpao'||id.startsWith('deb_gal_')||id.startsWith('deb_ord_gal_')||/^galp[aã]o|^estoque\/galp[aã]o/i.test(desc))return'galpao';if(['pdv','loja'].includes(o)||id.startsWith('deb_pdv_')||/^(pdv|loja):/i.test(desc))return'loja';return''}
  function injectDebtReport(){
    const section=$('#debitos'),anchor=$('#dResumoFiltro')?.closest('.card');if(!section||!anchor||$('#v133DebtGoods'))return;const box=document.createElement('div');box.id='v133DebtGoods';box.className='card v133-debt-card';box.innerHTML='<div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><h3 style="margin:0">🛒 MERCADORIAS RETIRADAS — GALPÃO E LOJA</h3><small class="muted">Relação somente dos produtos lançados como débito dos produtores.</small></div><div id="v133DebtSummary" class="muted"></div></div><div class="v133-debt-tools"><select id="v133DebtSource"><option value="">Galpão e Loja</option><option value="galpao">Somente Galpão</option><option value="loja">Somente Loja / PDV</option></select><input id="v133DebtSearch" placeholder="Pesquisar produtor, localidade ou produto..."></div><div id="v133DebtRows"></div>';anchor.insertAdjacentElement('afterend',box);$('#v133DebtSource').onchange=renderGoodsDebts;$('#v133DebtSearch').oninput=renderGoodsDebts;renderGoodsDebts();
  }
  function renderGoodsDebts(){
    const out=$('#v133DebtRows');if(!out)return;let all=[];try{all=typeof debitos!=='undefined'&&Array.isArray(debitos)?debitos:JSON.parse(localStorage.getItem('vds_debitos_v1')||'[]')}catch(_){}const filter=$('#v133DebtSource')?.value||'',q=String($('#v133DebtSearch')?.value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const rows=all.filter(d=>debtSource(d)&&(!filter||debtSource(d)===filter)).map(d=>{let p=null;try{if(typeof prodById==='function')p=prodById(d.prodId)}catch(_){}return{d,p}}).filter(x=>!q||[x.p?.nome,x.p?.local,x.d.descricao,JSON.stringify(x.d.itens||[])].join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)).sort((a,b)=>String(b.d.data||'').localeCompare(String(a.d.data||'')));let original=0,balance=0;const html=rows.map(({d,p})=>{let paid=0,saldo=Number(d.valor||0);try{if(typeof totalPagoDebito==='function')paid=totalPagoDebito(d.id);if(typeof saldoDebito==='function')saldo=saldoDebito(d.id)}catch(_){}original+=Number(d.valor||0);balance+=saldo;const items=Array.isArray(d.itens)&&d.itens.length?d.itens.map(i=>`${esc(i.produto||i.product_name||'Produto')} — ${num(i.quantidade??i.quantity)} ${esc(i.unidade||i.unit||'un')} • ${money(i.subtotal)}`).join('<br>'):esc(d.descricao||'-');return `<div class="v133-debt-row"><span><b>${esc(String(d.data||'').split('-').reverse().join('/'))}</b></span><span><b>${esc(p?.nome||'Produtor')}</b><small>${esc(p?.local||'-')}</small></span><span class="v133-source ${debtSource(d)==='loja'?'loja':''}">${debtSource(d)==='loja'?'LOJA / PDV':'GALPÃO'}</span><span>${items}</span><span><b>${money(d.valor)}</b><small>Pago ${money(paid)}</small></span><span><b style="color:${saldo>0?'#b52c2c':'#168638'}">${money(saldo)}</b><small>${saldo>0?'Pendente':'Pago'}</small></span></div>`}).join('');out.innerHTML='<div class="v133-debt-row v133-debt-head"><span>Data</span><span>Produtor</span><span>Origem</span><span>Produtos retirados</span><span>Valor</span><span>Saldo</span></div>'+(html||'<div style="padding:20px;text-align:center;color:#718096">Nenhuma mercadoria encontrada.</div>');$('#v133DebtSummary').innerHTML=`${rows.length} débito(s) • Total: <b>${money(original)}</b> • Saldo: <b>${money(balance)}</b>`;
  }
  window.v133RenderMercadorias=renderGoodsDebts;
  function fixMilkDebtSettlement(){if(typeof totalPagoDebito!=='function'||typeof saldoDebito!=='function'||totalPagoDebito.__v133)return;const oldTotal=totalPagoDebito,paidWithMilk=id=>{try{return typeof pagamentos!=='undefined'&&Array.isArray(pagamentos)&&pagamentos.some(pg=>Array.isArray(pg.debitIds)&&pg.debitIds.some(x=>String(x)===String(id)))}catch(_){return false}},total=function(id){if(paidWithMilk(id)){try{const d=debitos.find(x=>String(x.id)===String(id));return Number(d?.valor||0)}catch(_){}}return oldTotal(id)};total.__v133=true;try{totalPagoDebito=total;saldoDebito=function(id){try{const d=debitos.find(x=>String(x.id)===String(id));return d?Math.max(0,Number(d.valor||0)-totalPagoDebito(id)):0}catch(_){return 0}}}catch(_){}}
  function wrapStoreApi(){if(typeof ljApi!=='function'||ljApi.__v133)return;const old=ljApi,wrapped=async function(url,opt={}){const result=await old.apply(this,arguments);try{const body=opt.body?JSON.parse(opt.body):null;if(String(url)==='/api/store/sales'&&String(opt.method||'GET').toUpperCase()==='POST'&&String(body?.payment_method||'').toLowerCase()==='leite')await updateDebts()}catch(_){}return result};wrapped.__v133=true;try{ljApi=wrapped}catch(_){}}

  function bind(){
    document.querySelectorAll('[data-v133-close]').forEach(b=>b.onclick=()=>show(b.dataset.v133Close,false));
    $('#v133New')?.addEventListener('click',()=>openOrder());$('#v133List')?.addEventListener('click',openOrders);$('#v133Add')?.addEventListener('click',addItem);$('#v133Save')?.addEventListener('click',saveOrder);$('#v133ConfirmRelease')?.addEventListener('click',confirmRelease);$('#v133Print80')?.addEventListener('click',()=>printReceipt('80'));$('#v133PrintA4')?.addEventListener('click',()=>printReceipt('a4'));$('#v133Share')?.addEventListener('click',shareReceipt);$('#v133ProducerSearch')?.addEventListener('input',e=>producerOptions(e.target.value));
    document.querySelectorAll('[data-v133-pay]').forEach(b=>b.onclick=()=>{S.payment=b.dataset.v133Pay;document.querySelectorAll('[data-v133-pay]').forEach(x=>x.classList.toggle('sel',x===b))});document.querySelectorAll('[data-v133-status]').forEach(b=>b.onclick=()=>{S.status=b.dataset.v133Status;document.querySelectorAll('[data-v133-status]').forEach(x=>x.classList.toggle('sel',x===b));loadOrders()});
    document.addEventListener('click',e=>{const b=e.target.closest('[data-v133-remove],[data-v133-whatsapp],[data-v133-separate],[data-v133-edit],[data-v133-release],[data-v133-cancel],[data-v133-receipts],[data-v133-open-receipt]');if(!b)return;if(b.dataset.v133Remove){S.cart=S.cart.filter(x=>String(x.product_id)!==String(b.dataset.v133Remove));renderCart()}else if(b.dataset.v133Whatsapp)shareOrderStatus(b.dataset.v133Whatsapp);else if(b.dataset.v133Separate)separateOrder(b.dataset.v133Separate);else if(b.dataset.v133Edit)openOrder(S.orders.find(x=>String(x.id)===String(b.dataset.v133Edit)));else if(b.dataset.v133Release)openRelease(b.dataset.v133Release);else if(b.dataset.v133Cancel)cancelOrder(b.dataset.v133Cancel);else if(b.dataset.v133Receipts)openReleaseHistory(b.dataset.v133Receipts);else if(b.dataset.v133OpenReceipt)openReleaseById(b.dataset.v133Order,b.dataset.v133OpenReceipt)});
  }
  function wrapDebtRender(){const old=typeof renderDebitos==='function'?renderDebitos:null;if(old&&!old.__v133){const wrapped=function(){const r=old.apply(this,arguments);setTimeout(renderGoodsDebts,0);return r};wrapped.__v133=true;try{renderDebitos=wrapped}catch(_){}}}
  function boot(){injectStyles();injectOrderUi();bind();enhanceDesktop();fixMilkDebtSettlement();injectDebtReport();wrapStoreApi();wrapDebtRender();try{if(typeof renderDebitos==='function')renderDebitos()}catch(_){}setTimeout(updatePendingBadge,500)}
